def transform(grid):
    cells = {(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 8}
    tiles = []
    for r in range(len(grid) - 1):
        for c in range(len(grid[0]) - 1):
            box = {(r+i, c+j) for i in range(2) for j in range(2)}
            if box <= cells:
                tiles.append((box, 1))
            # The three-cell L shapes are colored by the missing corner.
            for missing, color in [((r, c), 2), ((r+1, c), 3), ((r, c+1), 4)]:
                shape = box - {missing}
                if shape <= cells:
                    tiles.append((shape, color))
    by_cell = {p: [tile for tile in tiles if p in tile[0]] for p in cells}
    answer = None
    def search(remaining, chosen):
        nonlocal answer
        if not remaining:
            out = [[0 for _ in row] for row in grid]
            for shape, color in chosen:
                for r, c in shape:
                    out[r][c] = color
            answer = out
            return True
        p = min(remaining, key=lambda q: sum(shape <= remaining for shape, _ in by_cell[q]))
        for shape, color in by_cell[p]:
            if shape <= remaining and search(remaining - shape, chosen + [(shape, color)]):
                return True
        return False
    if not search(cells, []):
        return [row[:] for row in grid]
    return answer
